<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { Plus, Search, UsersRound } from 'lucide-vue-next';
import { authRequest, clearSession, currentUser, type User } from '../auth';
import { v2 } from '../v2/api';
import { notify } from '../store';
import Modal from './Modal.vue';
const accounts=ref<User[]>([]),roles=ref<{code:string;name:string;permissions:string[]}[]>([]),departments=ref<{code:string;name:string}[]>([]);
const error=ref(''),busy=ref(false),loading=ref(false),search=ref(''),editing=ref<User|null>(null),opened=ref(false),resetTarget=ref<User|null>(null),resetPassword=ref('');
const form=ref({username:'',displayName:'',roleCode:'dept_liaison',deptCode:'',clauseText:'',password:'',status:'active'});
const rows=computed(()=>accounts.value.filter(a=>`${a.username} ${a.displayName} ${a.roleName} ${a.deptName||''}`.includes(search.value)));
const scoped=computed(()=>['dept_head','dept_liaison','quality_reviewer','expert'].includes(form.value.roleCode));
async function load(){loading.value=true;error.value='';try{accounts.value=(await authRequest<{items:User[]}>('/accounts')).items;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function open(account:User|null){editing.value=account;form.value={username:account?.username||'',displayName:account?.displayName||'',roleCode:account?.roleCode||'dept_liaison',deptCode:account?.deptCode||departments.value[0]?.code||'',clauseText:account?.clauseCodes.join(', ')||'',password:'',status:account?.status||'active'};opened.value=true;}
async function save(){busy.value=true;try{const f=form.value;const body:Record<string,unknown>={displayName:f.displayName,roleCode:f.roleCode,deptCode:scoped.value?f.deptCode:'',clauseCodes:f.roleCode==='expert'?f.clauseText.split(/[,，\s]+/).filter(Boolean):[],status:f.status};if(!editing.value){body.username=f.username;if(f.password)body.password=f.password;delete body.status;}await authRequest(`/accounts${editing.value?'/'+editing.value.id:''}`,{method:editing.value?'PATCH':'POST',body:JSON.stringify(body)});opened.value=false;notify('账号已保存，旧会话按服务端规则失效');await load();}catch(e){notify((e as Error).message,true);}finally{busy.value=false;}}
async function toggle(account:User){busy.value=true;try{await authRequest(`/accounts/${account.id}`,{method:'PATCH',body:JSON.stringify({status:account.status==='active'?'disabled':'active'})});notify('账号状态已更新');await load();}catch(e){notify((e as Error).message,true);}finally{busy.value=false;}}
async function reset(){if(!resetTarget.value)return;busy.value=true;try{await authRequest(`/accounts/${resetTarget.value.id}/reset-password`,{method:'POST',body:JSON.stringify(resetPassword.value?{password:resetPassword.value}:{})});if(resetTarget.value.id===currentUser.value?.id)clearSession();else notify('密码已重置，原会话已失效');resetTarget.value=null;resetPassword.value='';}catch(e){notify((e as Error).message,true);}finally{busy.value=false;}}
onMounted(async()=>{await load();try{const [r,d]=await Promise.all([authRequest<{items:typeof roles.value}>('/roles'),v2<{items:typeof departments.value}>('/departments')]);roles.value=r.items;departments.value=d.items;}catch(e){error.value=(e as Error).message;}});
</script>
<template><div class="page-intro"><div><h2>本院账号管理</h2><p>配置账号身份、实际科室与专家授权条款；权限由服务器统一管理。</p></div><button class="button primary" :disabled="busy||!roles.length" @click="open(null)"><Plus :size="16"/>新增账号</button></div><div class="info-strip"><UsersRound :size="18"/>{{currentUser?.hospitalName}} · {{accounts.length}} 个账号 · 账号变更即时影响其会话</div><div v-if="error" class="error-box">{{error}}</div>
<section class="card table-card"><div class="section-heading"><h3>账号目录</h3><div class="search-box compact"><Search :size="15"/><input v-model="search" aria-label="搜索账号" placeholder="姓名、账号、角色或科室"/></div></div><div class="table-wrap"><table><thead><tr><th>姓名 / 账号</th><th>角色</th><th>科室 / 范围</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td><strong>{{a.displayName}}</strong><small class="cell-sub">{{a.username}}</small></td><td>{{a.roleName}}</td><td>{{a.deptName||'本院'}}<small v-if="a.clauseCodes.length" class="cell-sub">{{a.clauseCodes.join('、')}}</small></td><td><span class="badge" :class="a.status==='active'?'badge-green':'badge-red'">{{a.status==='active'?'正常':'已停用'}}</span></td><td><div class="inline-filters"><button class="button-small" :disabled="busy" @click="open(a)">编辑</button><button class="button-small" :disabled="busy||a.id===currentUser?.id" @click="toggle(a)">{{a.status==='active'?'停用':'启用'}}</button><button class="button-small" :disabled="busy" @click="resetTarget=a;resetPassword=''">重置密码</button></div></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty">{{loading?'正在读取账号…':'暂无匹配账号'}}</td></tr></tbody></table></div></section>
<Modal v-if="opened" :title="editing?'编辑账号':'新增账号'" @close="!busy&&(opened=false)"><form @submit.prevent="save"><div class="form-grid"><label class="field">账号<input v-model="form.username" :disabled="!!editing||busy" required autocomplete="off"/></label><label class="field">姓名<input v-model="form.displayName" required :disabled="busy"/></label><label class="field">角色<select v-model="form.roleCode" :disabled="busy||editing?.id===currentUser?.id"><option v-for="r in roles" :key="r.code" :value="r.code">{{r.name}}</option></select></label><label v-if="scoped" class="field">授权科室<select v-model="form.deptCode" required :disabled="busy"><option v-for="d in departments" :key="d.code" :value="d.code">{{d.name}}（{{d.code}}）</option></select></label></div><label v-if="form.roleCode==='expert'" class="field">授权条款（逗号分隔）<input v-model="form.clauseText" required placeholder="CL-2.1, CL-2.2" :disabled="busy"/><small>条款有效性与科室范围由服务器校验</small></label><label v-if="!editing" class="field">初始密码（可选）<input v-model="form.password" type="password" minlength="10" maxlength="256" autocomplete="new-password" :disabled="busy"/><small>留空使用统一初始密码</small></label><p class="hint">{{roles.find(r=>r.code===form.roleCode)?.permissions.join(' · ')}}</p><div class="form-actions"><button type="button" class="button" :disabled="busy" @click="opened=false">取消</button><button class="button primary" :disabled="busy">{{busy?'保存中…':'保存账号'}}</button></div></form></Modal>
<Modal v-if="resetTarget" title="重置账号密码" @close="!busy&&(resetTarget=null)"><form @submit.prevent="reset"><p>将重置 {{resetTarget.displayName}}（{{resetTarget.username}}）的密码，已有会话立即失效。</p><label class="field">新密码（可选）<input v-model="resetPassword" type="password" minlength="10" maxlength="256" autocomplete="new-password" :disabled="busy"/><small>留空使用统一初始密码</small></label><div class="form-actions"><button type="button" class="button" :disabled="busy" @click="resetTarget=null">取消</button><button class="button primary" :disabled="busy">确认重置</button></div></form></Modal></template>
